def sha(b):
    return hashlib.sha256(b).hexdigest()

def main():
    report = ROOT/'docs/checks/skills-repair'
    retries = json.loads((report/'group-b-retry-names.json').read_text(encoding='utf-8'))
    assert set(retries) == set(PATCHES) and len(PATCHES) == 17
    changes_path = report/'group-b-changes.json'
    changes = json.loads(changes_path.read_text(encoding='utf-8'))
    before_untouched = {x['name']: sha((ROOT/'workspace/.dsh/skills'/x['name']/'SKILL.md').read_bytes()) for x in changes if x['name'] not in PATCHES}
    for row in changes:
        name = row['name']
        if name not in PATCHES:
            continue
        path = ROOT/'workspace/.dsh/skills'/name/'SKILL.md'
        raw = path.read_bytes()
        assert sha(raw) == row['afterSha256'], name
        backup = report/'round1-before'/name/'SKILL.md'
        assert not backup.exists(), f'One repair only: {name}'
        text = raw.decode('utf-8')
        for old, new in PATCHES[name]:
            assert text.count(old) == 1, name
            text = text.replace(old, new)
        text = text.replace('<!-- workbench-skill-repair-v2 -->', '<!-- workbench-skill-repair-v2 -->\n<!-- group-b-one-repair-after-round1 -->', 1)
        backup.parent.mkdir(parents=True,exist_ok=True)
        backup.write_bytes(raw)
        path.write_text(text,encoding='utf-8',newline='\n')
        row['round1AfterSha256'] = sha(raw)
        row['afterSha256'] = sha(path.read_bytes())
        row['criticalChecks'].append('按54份实测反例作一次字段结构补救，待旧题与新题复测')
    for name, expected in before_untouched.items():
        assert sha((ROOT/'workspace/.dsh/skills'/name/'SKILL.md').read_bytes()) == expected, name
    changes_path.write_text(json.dumps(changes,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Patched 17 failing skills once; 10 passing skills unchanged; initial before SHA preserved.')

if __name__ == '__main__':
    main()
